def parse_cli(argv):
    args = argv[1:]
    opts = {
        'h': False, 'H': False, 'I': [], 'W': False, 'u': False, 'd': None, 'V': False,
        'S': None, 'U': None, 'r': False, 'R': False, 'c': [], 'f': [], 'e': [],
        't': False, 'n': False, 'N': False, 'q': False, 'C': False, 'i': False, 'm': False,
        'D': False, 'v_count': 0, 'q_count': 0,
