    i = 0
    end_options = False
    # Helper to record missing
    def record_missing(opt_key, msg):
        nonlocal missing_error
        if missing_error is None:
            missing_error = (opt_key, msg)
    # Parse loop
    while i < len(args):
        tok = args[i]
        if end_options:
            positionals.append(tok)
            i += 1
            continue
        if tok == "--":
            end_options = True
            i += 1
            continue
        # Long options
        if tok.startswith("--"):
            if "=" in tok:
                opt, val = tok.split("=", 1)
                # opt is --since, --until, etc.
