                        elif ch == 'd':
                            record_missing('-d', "-d: 1 required FILE missing")
                        elif ch == 'S':
                            record_missing('--since', "--since: 1 required TEXT missing")
                        elif ch == 'U':
                            record_missing('--until', "--until: 1 required TEXT missing")
                        elif ch == 'c':
                            record_missing('-c', "-c: 1 required  missing")
                        elif ch == 'f':
                            record_missing('-f', "-f: 1 required  missing")
                        elif ch == 'e':
