                                elif ch == 'f':
                                    record_missing('-f', "-f: 1 required  missing")
                                elif ch == 'e':
                                    record_missing('-e', "-e: 1 required  missing")
                                consumed_next = False
                                j = len(chars)
                                break
                            else:
                                val = args[i+1]
                                if ch == 'I':
                                    opts['I'].append(val)
                                elif ch == 'd':
                                    opts['d'] = val
                                elif ch == 'S':
                                    opts['S'] = val
                                elif ch == 'U':
                                    opts['U'] = val
                                elif ch == 'c':
                                    opts['c'].append(val)
                                    cmds_order.append(('c', val))
                                elif ch == 'f':
                                    opts['f'].append(val)
